import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('melasma-facial-melanosis',
  kf=["**Melasma** is acquired, symmetrical brown patches on the face (cheeks, forehead, upper lip, chin), driven by **UV, visible light and hormones**.",
      "Commonest in women with Fitzpatrick III–V skin; triggered by pregnancy ('mask of pregnancy') and the combined pill.",
      "Wood's light or dermoscopy suggests epidermal versus dermal pigment; dermal pigment responds poorly.",
      "Foundation: daily **tinted** broad-spectrum SPF 30–50 (iron oxides block visible light); azelaic acid 15–20%; avoid unregulated bleaching creams.",
      "Specialist: triple-combination creams, tranexamic acid, peels; relapse is common. Consider drug-induced pigmentation and exogenous ochronosis."],
  epi=[{"t": "**Who**", "sub": ["About 90% are women; onset in the 20s–40s; common in Latin American, East and South Asian, Middle Eastern and African skin.", "Family history in about half."]}],
  aet=["Sun (UVA, UVB and **visible light**), oestrogen and progesterone, heat, genetics; possibly thyroid disease.", "Irritant cosmetics, phototoxic products."],
  myths=["**\"SPF 50 alone is enough\"**: ordinary sunscreens do not block visible light; use a tinted one.", "**\"Stronger bleach works faster\"**: high-strength hydroquinone or mercury/steroid creams cause ochronosis and harm."],
  patho_lead="In melasma, **overactive melanocytes** and a damaged dermis keep producing pigment.",
  mech=[("Triggers", "UV and visible light, heat and hormones stimulate melanocytes and keratinocytes."),
        ("Melanocyte overactivity", "Melanocytes enlarge and transfer more melanin to keratinocytes (epidermal melasma).", "v4-melasma-melanocytes.jpg", "Melasma: light and hormones stimulate enlarged melanocytes to pass extra pigment into the epidermis; some pigment drops into dermal melanophages."),
        ("Dermal pigment", "Pigment falls into the dermis and is taken up by melanophages; this dermal component is hard to treat."),
        ("Dermal signalling", "Solar elastosis, increased blood vessels and a damaged basement membrane keep stimulating melanocytes, explaining relapse.")],
  histo=["Increased epidermal melanin, prominent melanocytes, dermal melanophages, solar elastosis and vessels. Biopsy rarely needed."],
  special=[{"t": "**Pregnancy**", "sub": ["Often fades after delivery; azelaic acid is the safer option; avoid retinoids and hydroquinone."]}],
  comp=["Psychological impact; post-inflammatory hyperpigmentation from irritating treatments; exogenous ochronosis from hydroquinone."],
  prog=["Chronic and relapsing, worse in summer; strict photoprotection is lifelong."],
  see_also=["drug-induced-pigmentation", "solar-lentigines", "photoageing", "hypopigmentation-skin-of-colour", "contact-lichenoid-pigmentation"])

E('photoageing',
  kf=["**Photoageing** is premature skin ageing from chronic UV (and visible/infrared) exposure, on top of intrinsic ageing.",
      "Wrinkles, coarse texture, mottled pigment, solar lentigines, telangiectasia, yellowish thickening (**solar elastosis**).",
      "Marks cumulative sun damage and higher risk of AK, BCC, SCC and melanoma: examine the skin.",
      "Prevention: sun protection and stopping smoking; topical **retinoids** have the best evidence for treatment.",
      "Procedures (peels, lasers, injectables) are cosmetic and not NHS-funded."],
  epi=[{"t": "**Who**", "sub": ["Fair skin, outdoor workers, sunbed users, sunny climates; smoking adds damage."]}],
  aet=["UVA penetrates the dermis (collagen and elastin damage); UVB damages the epidermis and DNA.", "Smoking, pollution, infrared radiation."],
  myths=["**\"A tan protects the skin\"**: a tan is a sign of DNA damage.", "**\"Anti-ageing creams reverse wrinkles\"**: only retinoids and sun protection have good evidence."],
  patho_lead="UV turns on **collagen-destroying enzymes** while slowing new collagen formation.",
  mech=[("Free radicals", "UV generates reactive oxygen species in skin cells."),
        ("Matrix breakdown", "Signalling (AP-1) switches on matrix metalloproteinases that digest collagen."),
        ("Reduced repair", "New collagen synthesis falls; fragmented collagen weakens the dermis: wrinkles."),
        ("Solar elastosis", "Abnormal elastic material builds up in the upper dermis, causing yellow, thickened skin."),
        ("Pigment and vessels", "Uneven melanocyte activity (lentigines) and dilated vessels (telangiectasia) appear.")],
  histo=["Solar elastosis (blue-grey amorphous elastic material in the papillary dermis), reduced collagen, atrophic or uneven epidermis."],
  special=[{"t": "**Skin of colour**", "sub": ["Photoageing appears later and is mainly pigmentary (uneven tone, dermatosis papulosa nigra) rather than wrinkles."]}],
  comp=["Actinic keratoses and skin cancers; skin fragility, purpura and skin tears."],
  prog=["Partly preventable and partly reversible with photoprotection and retinoids."],
  see_also=["solar-lentigines", "actinic-keratoses", "skin-fragility-dermatoporosis", "retinoids", "facial-ageing-neuromodulators"])

E('solar-lentigines',
  kf=["**Solar lentigines** ('liver spots', 'age spots') are flat, well-defined brown macules on sun-exposed skin.",
      "Face, backs of hands, forearms and shoulders in middle-aged and older adults; a marker of sun damage.",
      "Dermoscopy: fine reticular pattern, 'moth-eaten' edges, fingerprint pattern.",
      "Differentiate from **lentigo maligna** (irregular, enlarging, multiple colours on the face) and pigmented AK or SK.",
      "Benign: sun protection; cryotherapy or laser are cosmetic options."],
  epi=[{"t": "**Who**", "sub": ["Over 90% of fair-skinned people over 60; increase with age and sun exposure."]}],
  aet=["Chronic UV exposure; PUVA and sunbeds produce similar lentigines."],
  myths=["**\"They're harmless so never need checking\"**: a changing, irregular facial lentigo may be lentigo maligna."],
  patho_lead="UV causes a **local increase in melanocytes** and pigment along the basal layer.",
  mech=[("UV injury", "Repeated UV exposure stimulates basal melanocytes."),
        ("Melanocyte increase", "Melanocyte numbers increase modestly along the basal layer (no nests)."),
        ("Elongated rete ridges", "Rete ridges lengthen and are heavily pigmented, creating a flat brown patch.")],
  histo=["Elongated, club-shaped, pigmented rete ridges with a slight increase in single basal melanocytes; no atypia."],
  special=[{"t": "**Lentigo maligna warning**", "sub": ["Asymmetric pigmentation, multiple colours, grey dots, enlargement: refer via the suspected cancer pathway."]}],
  comp=["Cosmetic concern; may evolve into a flat seborrhoeic keratosis (reticulated SK)."],
  prog=["Persist and increase; fade slightly with strict sun protection."],
  see_also=["seborrhoeic-keratosis", "melanoma", "photoageing", "melasma-facial-melanosis", "actinic-keratoses"])

E('polymorphic-light-eruption',
  kf=["**Polymorphic light eruption (PLE)** is the commonest photodermatosis: itchy papules, vesicles or plaques hours to days after the first strong sun of spring or a holiday.",
      "Affects exposed skin that is usually covered in winter (V of neck, arms), sparing the face often; settles over days without sun.",
      "Tends to improve over the summer ('hardening').",
      "Prevention: sun protection, gradual exposure; potent topical steroid for 5–7 days for flares.",
      "Refer if severe for prophylactic phototherapy (hardening); exclude lupus (check ANA/Ro if suspicious)."],
  epi=[{"t": "**Who**", "sub": ["Up to 1 in 5 people in northern Europe; women more; onset in the teens to 30s."]}],
  aet=["Delayed-type hypersensitivity to a UV-induced skin antigen, with failure of normal UV immunosuppression.", "Mainly UVA; can occur through window glass."],
  myths=["**\"It's an allergy to sunscreen\"**: PLE is a reaction to light itself, although sunscreen allergy can occur."],
  patho_lead="Normally UV **dampens skin immunity**; in PLE this fails and the immune system attacks UV-altered skin.",
  mech=[("UV antigen", "UV (mainly UVA) alters skin proteins, creating new antigens."),
        ("Failed suppression", "Normal UV-induced immunosuppression (Langerhans cell migration, regulatory T cells) does not occur."),
        ("Delayed hypersensitivity", "T cells react hours to days later, producing itchy papules and vesicles."),
        ("Hardening", "Repeated gradual exposure restores tolerance, so PLE eases as summer goes on.")],
  histo=["Papillary dermal oedema with a perivascular lymphocytic infiltrate; spongiosis. Biopsy if lupus is suspected."],
  special=[{"t": "**Skin of colour**", "sub": ["Pinpoint papular variant common; may look skin-coloured or hypopigmented."]}],
  comp=["Distress and holiday disruption; rare link with later lupus or autoimmune thyroid disease."],
  prog=["Recurs each spring for years; often improves with age."],
  see_also=["drug-photosensitivity", "chronic-actinic-dermatitis", "discoid-lupus", "phytophotodermatitis", "urticaria-angioedema"])

E('drug-photosensitivity',
  kf=["**Drug photosensitivity** is a rash on sun-exposed skin caused by a drug plus UV (mostly UVA).",
      "**Phototoxic** (commonest, dose-related, 'exaggerated sunburn') versus **photoallergic** (eczematous, immune).",
      "Common culprits: tetracyclines (doxycycline), thiazides, amiodarone, voriconazole, NSAIDs, quinolones, phenothiazines.",
      "Sharp cut-off at clothing lines; spares under the chin, behind the ears and skin folds.",
      "Stop or switch the culprit with the prescriber (never stop amiodarone, voriconazole or antiretrovirals without specialist input); strict UVA protection."],
  epi=[{"t": "**Who**", "sub": ["Common in older people on multiple drugs; holiday or summer onset."]}],
  aet=["Photosensitising drug in the skin plus UVA (passes through window glass)."],
  myths=["**\"Sunscreen fixes it\"**: many sunscreens protect poorly against UVA; clothing and avoiding sun matter."],
  patho_lead="A drug in the skin **absorbs UV energy** and damages cells directly or creates an allergen.",
  mech=[("Drug in skin", "The drug or its metabolite reaches the dermis and epidermis."),
        ("Phototoxic", "Absorbed UVA excites the drug, releasing free radicals that damage cells: sunburn-like reaction within hours."),
        ("Photoallergic", "UV converts the drug into a hapten; T cells become sensitised: eczema days later, may spread beyond exposed sites."),
        ("Pigmentation", "Some drugs (amiodarone, minocycline) leave slate-grey or blue pigment in exposed skin.")],
  histo=["Phototoxic: necrotic keratinocytes like sunburn. Photoallergic: spongiotic dermatitis. Phototesting confirms in specialist units."],
  special=[{"t": "**Photo-onycholysis**", "sub": ["Tetracyclines and psoralens can lift the nails from the bed after sun exposure."]}],
  comp=["Blistering, pigmentation, persistent light reaction (chronic actinic dermatitis)."],
  prog=["Phototoxic reactions clear when the drug stops (amiodarone may take months); photoallergy can persist."],
  see_also=["polymorphic-light-eruption", "phytophotodermatitis", "chronic-actinic-dermatitis", "drug-induced-pigmentation", "drug-eruption-approach"])

E('scarlet-fever',
  kf=["**Scarlet fever** is a group A streptococcal (*S. pyogenes*) infection with a toxin-mediated rash; commonest in children aged 2–8.",
      "Sore throat, fever, then a **sandpaper** rash (neck, chest, flexures), flushed cheeks with **circumoral pallor**, **strawberry tongue**, Pastia lines.",
      "**Phenoxymethylpenicillin for 10 days**; clarithromycin or azithromycin if penicillin allergic.",
      "**Notifiable**; exclude from school or work until 24 hours after starting antibiotics.",
      "Watch for **invasive group A strep** (iGAS): fever with severe illness, spreading cellulitis, necrotising signs: same-day emergency care."],
  epi=[{"t": "**Who**", "sub": ["Children 2–8 years in winter and spring; outbreaks in schools and nurseries.", "UK outbreaks rose sharply in 2022–23 with more iGAS."]}],
  aet=["Streptococcal **pyrogenic exotoxins** (SpeA, SpeC) act as superantigens."],
  myths=["**\"Scarlet fever is a disease of the past\"**: it is common again in the UK."],
  patho_lead="The rash is caused by **toxins**, not by bacteria in the skin.",
  mech=[("Pharyngeal infection", "GAS infects the throat or tonsils (occasionally skin or wounds)."),
        ("Exotoxin release", "Pyrogenic exotoxins act as **superantigens**, activating many T cells non-specifically."),
        ("Rash", "Cytokines dilate dermal capillaries, giving the fine sandpaper erythema, flushed face and strawberry tongue.", "v3-scarlet-fever-face.jpg", "Flushed cheeks with circumoral pallor."),
        ("Tongue changes", "White-coated then red 'strawberry' tongue.", "v3-strawberry-tongue-stages.jpg", "White then red strawberry tongue."),
        ("Desquamation", "Peeling of fingertips and toes after 1–2 weeks.")],
  histo=["Not needed. Throat swab for culture or rapid antigen test supports diagnosis (UKHSA)."],
  special=[{"t": "**Chickenpox or influenza co-infection**", "sub": ["Higher risk of iGAS: low threshold for review."]}],
  comp=["Otitis media, quinsy, sinusitis, pneumonia.", "**iGAS**: necrotising fasciitis, sepsis, toxic shock.", "Late: rheumatic fever, post-streptococcal glomerulonephritis."],
  prog=["Recovers within a week with antibiotics."],
  see_also=["cellulitis-erysipelas", "impetigo", "morbilliform-drug-eruption", "neonatal-rashes"])
